import Database from 'better-sqlite3';
import path from 'path';

const dbPath = '/home/user/qwik-app/metadata.db';

export const db = new Database(dbPath);

// Initialize table
db.exec(`
  CREATE TABLE IF NOT EXISTS files (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    size INTEGER NOT NULL,
    mime TEXT NOT NULL,
    tag TEXT NOT NULL
  )
`);

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';
import fs from 'fs';
import path from 'path';

export const onPost: RequestHandler = async ({ request, json }) => {
  try {
    const formData = await request.formData();
    const file = formData.get('file');
    const tag = formData.get('tag');

    if (!file || typeof file === 'string' || !file.name) {
      return json(400, { error: 'File is missing or invalid' });
    }

    if (!tag || typeof tag !== 'string' || tag.trim() === '') {
      return json(400, { error: 'Tag is missing or invalid' });
    }

    const uploadDir = '/home/user/qwik-app/public/uploads';
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }

    const filePath = path.join(uploadDir, file.name);
    const arrayBuffer = await file.arrayBuffer();
    fs.writeFileSync(filePath, Buffer.from(arrayBuffer));

    const size = file.size;
    const mime = file.type || 'application/octet-stream';
    const name = file.name;

    const stmt = db.prepare(
      'INSERT INTO files (name, size, mime, tag) VALUES (?, ?, ?, ?)'
    );
    const result = stmt.run(name, size, mime, tag);
    const id = Number(result.lastInsertRowid);

    return json(201, {
      id,
      name,
      size,
      mime,
      tag,
    });
  } catch (error: any) {
    return json(400, { error: error.message || 'An error occurred during upload' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';

export const onGet: RequestHandler = async ({ json }) => {
  try {
    const rows = db.prepare('SELECT id, name, size, mime, tag FROM files').all();
    return json(200, rows);
  } catch (error: any) {
    return json(500, { error: error.message || 'An error occurred while listing files' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';
import fs from 'fs';
import path from 'path';

export const onDelete: RequestHandler = async ({ params, json }) => {
  try {
    const idStr = params.id;
    const id = parseInt(idStr, 10);
    if (isNaN(id)) {
      return json(400, { error: 'Invalid ID format' });
    }

    // Check if the record exists in SQLite
    const row = db.prepare('SELECT name FROM files WHERE id = ?').get(id) as { name: string } | undefined;
    if (!row) {
      return json(404, { error: 'File ID does not exist in the database' });
    }

    // Try to delete physical file from disk
    const uploadDir = '/home/user/qwik-app/public/uploads';
    const filePath = path.join(uploadDir, row.name);
    try {
      if (fs.existsSync(filePath)) {
        fs.unlinkSync(filePath);
      }
    } catch (err) {
      // If physical file is missing or cannot be deleted, we still proceed to delete db record.
    }

    // Delete corresponding metadata record from SQLite database
    db.prepare('DELETE FROM files WHERE id = ?').run(id);

    return json(200, { success: true });
  } catch (error: any) {
    return json(500, { error: error.message || 'An error occurred during deletion' });
  }
};

import { component$, useStore, useVisibleTask$, $ } from "@builder.io/qwik";

export interface UploadedFile {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

export default component$(() => {
  const state = useStore({
    files: [] as UploadedFile[],
    errorMessage: "",
    successMessage: "",
  });

  const fetchFiles = $(async () => {
    try {
      const response = await fetch("/files/list");
      if (response.ok) {
        state.files = await response.json();
      } else {
        state.errorMessage = "Failed to load files";
      }
    } catch (err: any) {
      state.errorMessage = err.message || "Failed to load files";
    }
  });

  // Fetch files on mount
  useVisibleTask$(() => {
    fetchFiles();
  });

  const handleUpload = $(async (e: SubmitEvent) => {
    e.preventDefault();
    state.errorMessage = "";
    state.successMessage = "";

    const form = e.target as HTMLFormElement;
    const fileInput = form.querySelector("#file-input") as HTMLInputElement;
    const tagInput = form.querySelector("#tag-input") as HTMLInputElement;

    if (!fileInput || !fileInput.files || fileInput.files.length === 0) {
      state.errorMessage = "Please select a file to upload.";
      return;
    }

    if (!tagInput || !tagInput.value.trim()) {
      state.errorMessage = "Please provide a tag.";
      return;
    }

    const formData = new FormData();
    formData.append("file", fileInput.files[0]);
    formData.append("tag", tagInput.value.trim());

    try {
      const response = await fetch("/files/upload", {
        method: "POST",
        body: formData,
      });

      if (response.status === 201) {
        state.successMessage = "File uploaded successfully!";
        form.reset();
        await fetchFiles();
      } else {
        const errData = await response.json();
        state.errorMessage = errData.error || "Upload failed";
      }
    } catch (err: any) {
      state.errorMessage = err.message || "An error occurred during upload.";
    }
  });

  const handleDelete = $(async (id: number) => {
    state.errorMessage = "";
    state.successMessage = "";

    try {
      const response = await fetch(`/files/${id}`, {
        method: "DELETE",
      });

      if (response.ok) {
        state.successMessage = "File deleted successfully!";
        await fetchFiles();
      } else {
        const errData = await response.json();
        state.errorMessage = errData.error || "Deletion failed";
      }
    } catch (err: any) {
      state.errorMessage = err.message || "An error occurred during deletion.";
    }
  });

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>Server-Side File Explorer</h1>

      {state.errorMessage && (
        <div style={{ color: "red", marginBottom: "15px" }}>
          {state.errorMessage}
        </div>
      )}
      {state.successMessage && (
        <div style={{ color: "green", marginBottom: "15px" }}>
          {state.successMessage}
        </div>
      )}

      <form id="upload-form" onSubmit$={handleUpload} style={{ marginBottom: "30px" }}>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="file-input" style={{ display: "block", fontWeight: "bold" }}>File:</label>
          <input id="file-input" name="file" type="file" required />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="tag-input" style={{ display: "block", fontWeight: "bold" }}>Tag:</label>
          <input id="tag-input" name="tag" type="text" required placeholder="e.g., documents" />
        </div>
        <button type="submit">Upload File</button>
      </form>

      <h2>Uploaded Files</h2>
      <div id="file-list">
        {state.files.length === 0 ? (
          <p>No files uploaded yet.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "2px solid #ccc", textAlign: "left" }}>
                <th style={{ padding: "8px" }}>Name</th>
                <th style={{ padding: "8px" }}>Size (bytes)</th>
                <th style={{ padding: "8px" }}>MIME Type</th>
                <th style={{ padding: "8px" }}>Tag</th>
                <th style={{ padding: "8px" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {state.files.map((file) => (
                <tr key={file.id} style={{ borderBottom: "1px solid #eee" }}>
                  <td style={{ padding: "8px" }}>{file.name}</td>
                  <td style={{ padding: "8px" }}>{file.size}</td>
                  <td style={{ padding: "8px" }}>{file.mime}</td>
                  <td style={{ padding: "8px" }}>{file.tag}</td>
                  <td style={{ padding: "8px" }}>
                    <button
                      class="delete-btn"
                      data-id={file.id}
                      onClick$={() => handleDelete(file.id)}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
});

